const num = 100;
const bigNum = 100000000000000000000n;

console.log(typeof num);     // "number"
console.log(typeof bigNum);  // "bigint"

// BigInt is useful for very large integers
const largeNumber = 9007199254740993n;
console.log(largeNumber);

// Cannot mix Number and BigInt directly
// console.log(10 + 10n); // TypeError

// Convert explicitly if needed
console.log(10n + BigInt(10)); // 20n

console.log(10 / 0);
// Infinity

console.log(-10 / 0);
// -Infinity

console.log(typeof Infinity);
// "number"

console.log(Number.isFinite(Infinity));
// false

console.log(Number.isNaN(NaN));
// true

console.log(Number.isNaN("hello"));
// false

console.log(Number.isNaN("123"));
// false

console.log(Number.isNaN(123));
// false

console.log(isNaN("hello"));
// true
// "hello" is converted to a number, producing NaN.

console.log(isNaN("123"));
// false
// "123" is converted to 123.

console.log(Number.isNaN("hello"));
// false
// It is a string, not the NaN value.

console.log(Number.isNaN(NaN));
// true

console.log(0.1 + 0.2);
// 0.30000000000000004

console.log(0.1 + 0.2 === 0.3);
// false

// One common solution for comparisons:
const result = 0.1 + 0.2;
const expected = 0.3;

console.log(Math.abs(result - expected) < Number.EPSILON);
// true

const maxSafe = Number.MAX_SAFE_INTEGER;
console.log(maxSafe);
// 9007199254740991

const hugeValue = 900719925474099100000n;
console.log(hugeValue);

// BigInt supports exact integer arithmetic
const a = 1000000000000000000n;
const b = 2000000000000000000n;

console.log(a + b);
